 for(let radius=.1;radius<=2.01;radius+=.1){
  const samples=Math.ceil(2*Math.PI*radius/.08);
  for(let i=0;i<samples;i++){const angle=i/samples*Math.PI*2,x=p.x+Math.cos(angle)*radius,z=p.z+Math.sin(angle)*radius;
   if(!blocked(x,z)){camera.position.x=planWorldX(x+levels[active].origin.x);camera.position.z=z+levels[active].origin.z;const room=levels[active].rooms.find(r=>pointInPolygon(x,z,r.polygon));if(room)markRoom(room.id);return true;}
  }
 }
